<script setup>
import {Head,useForm,Link} from '@inertiajs/vue3';import AppLayout from '../Layouts/AppLayout.vue';
defineProps({exams:Object});const form=useForm({title:'',description:'',duration_minutes:120});const create=()=>form.post('/exams',{onSuccess:()=>form.reset('title','description')});
</script><template><Head title="Quản lý đề thi"/><AppLayout><h1>Quản lý đề thi</h1><div class="notice">Giai đoạn 1: tạo đề nháp. Chưa mở thi, chưa phát đề cho học viên.</div><div class="card"><h2>Tạo đề thi nháp</h2><form @submit.prevent="create"><div class="field"><label>Tên đề</label><input v-model="form.title" required/><small class="error">{{form.errors.title}}</small></div><div class="field"><label>Mô tả</label><textarea v-model="form.description"/></div><div class="field"><label>Thời lượng (phút)</label><input type="number" min="5" max="180" v-model.number="form.duration_minutes"/></div><button :disabled="form.processing">Tạo đề nháp</button></form></div><div class="card" style="margin-top:20px"><h2>Danh sách đề</h2><div class="tablewrap"><table><thead><tr><th>Mã đề</th><th>Tên đề</th><th>Câu hỏi</th><th>Phút</th><th>Trạng thái</th></tr></thead><tbody><tr v-for="e in exams.data" :key="e.id"><td>#{{e.id}}</td><td>{{e.title}}</td><td>{{e.questions_count}}</td><td>{{e.duration_minutes}}</td><td>{{e.status}}</td></tr></tbody></table></div><div class="pagination"><Link v-if="exams.prev_page_url" :href="exams.prev_page_url">← Trước</Link><span>Trang {{exams.current_page}} / {{exams.last_page}}</span><Link v-if="exams.next_page_url" :href="exams.next_page_url">Tiếp →</Link></div></div></AppLayout></template>
